    products,
    suppliers,
    locations,
    warehouses,
    categories,
    uoms,
    user_roles,
    users,
    role_permissions,
    roles,
    permissions
RESTART IDENTITY CASCADE;



SELECT '00000000-0000-0000-0000-000000000701', id
FROM permissions;

SELECT '00000000-0000-0000-0000-000000000702', id
FROM permissions
WHERE code IN (
    'WAREHOUSE_VIEW', 'WAREHOUSE_CREATE', 'WAREHOUSE_UPDATE',
    'PRODUCT_VIEW', 'PRODUCT_CREATE', 'PRODUCT_UPDATE', 'PRODUCT_LOCK',
    'CATEGORY_VIEW', 'CATEGORY_CREATE', 'CATEGORY_UPDATE',
    'UOM_VIEW', 'UOM_CREATE', 'UOM_UPDATE',
    'LOCATION_VIEW', 'LOCATION_CREATE', 'LOCATION_UPDATE',
