    'INBOUND_RECEIPT_CREATE', 'INBOUND_RECEIPT_UPDATE', 'INBOUND_RECEIPT_APPROVE', 'INBOUND_RECEIPT_DECLINE',
    'OUTBOUND_RECEIPT_CREATE', 'OUTBOUND_RECEIPT_UPDATE', 'OUTBOUND_RECEIPT_APPROVE', 'OUTBOUND_RECEIPT_DECLINE',
    'INVENTORY_VIEW', 'INVENTORY_DETAIL',
    'REPORT_VIEW',
    'GREEN_AGING_VIEW', 'GREEN_SLOW_VIEW', 'GREEN_EXPIRY_VIEW', 'GREEN_WASTE_VIEW'
);

